items.command:
"C:\\Users\\Admin\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '$ErrorActionPreference = '"'Stop'
"'$taskTargetDir = '"'C:\\Users\\Admin\\.codex\\worktrees\\communication-native-ui-files-02'
"'$taskPaths = @((Join-Path $taskTargetDir '"'message.md'), (Join-Path "'$taskTargetDir '"'message.txt'))
if (-not (Test-Path -LiteralPath "'$taskTargetDir -PathType Container)) { throw '"'指定目录不存在，未创建任何文件。' }
foreach ("'$taskPath in $taskPaths) {
    if (Test-Path -LiteralPath $taskPath) {
        Write-Output ('"'目标已存在：' + "'$taskPath)
        if (Test-Path -LiteralPath $taskPath -PathType Leaf) { Get-Content -LiteralPath $taskPath -Raw -Encoding utf8 }
        throw '"'目标已存在，未覆盖或创建任何文件。'
    }
}
"'$taskBody = '"'各位，请在周三16:00前提交草稿，周四10:00由李明负责合并。如无法按时完成，请在周二下班前告知。谢谢大家。'
"'$taskEncoding = [System.Text.UTF8Encoding]::new($false)
$taskBytes = $taskEncoding.GetBytes($taskBody)
foreach ($taskPath in $taskPaths) {
    $taskStream = [System.IO.File]::Open($taskPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
    try { $taskStream.Write($taskBytes, 0, $taskBytes.Length) } finally { $taskStream.Dispose() }
}
$taskMdRead = [System.IO.File]::ReadAllText($taskPaths[0], $taskEncoding)
$taskTxtRead = [System.IO.File]::ReadAllText($taskPaths[1], $taskEncoding)
if (-not [string]::Equals($taskMdRead, $taskBody, [System.StringComparison]::Ordinal)) { throw '"'message.md 与原始正文不一致。' }
if (-not [string]::Equals("'$taskTxtRead, $taskBody, [System.StringComparison]::Ordinal)) { throw '"'message.txt 与原始正文不一致。' }
if (-not [string]::Equals("'$taskMdRead, $taskTxtRead, [System.StringComparison]::Ordinal)) { throw '"'两个文件的正文不一致。' }
[pscustomobject]@{path="'$taskPaths[0]; readback=$taskMdRead; matches_original=$true} | ConvertTo-Json -Compress
[pscustomobject]@{path=$taskPaths[1]; readback=$taskTxtRead; matches_original=$true} | ConvertTo-Json -Compress
Write-Output '"'已分别回读：两者正文逐字一致，且与最初协调消息正文一致。'"

